package com.ultron.launcher;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
public final class AgendaReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context c,Intent intent){final PendingResult result=goAsync();new Thread(()->{try{
  if(!"com.ultron.launcher.AGENDA".equals(intent.getAction())){AgendaStore.reschedule(c);return;}
  String id=intent.getData()==null?"":intent.getData().getLastPathSegment();JSONArray rows=AgendaStore.list(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.getString("id").equals(id))continue;long at=row.getLong("startMs")-row.optInt("reminder",-1)*60000L;if(row.optInt("reminder",-1)<0||System.currentTimeMillis()<at-1000||System.currentTimeMillis()>at+900000||!AgendaStore.notifications(c))return;
   if(row.optBoolean("ring",false)){try{c.startForegroundService(new Intent(c,AgendaAlarmService.class).putExtra("id",id));}catch(RuntimeException e){fallback(c,row);}}else{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel("agenda-reminders","Promemoria UNVOR",NotificationManager.IMPORTANCE_HIGH);channel.setDescription("Appuntamenti e turni salvati sul Pixel");nm.createNotificationChannel(channel);nm.notify(id,1,notification(c,row,"agenda-reminders",false));}break;
  }
 }catch(Exception ignored){}finally{result.finish();}},"ultron-agenda-alert").start();}
 static void fallback(Context c,JSONObject row){try{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("agenda-reminders","Promemoria UNVOR",NotificationManager.IMPORTANCE_HIGH));Notification n=Notification.Builder.recoverBuilder(c,notification(c,row,"agenda-reminders",false)).setContentText("Sveglia sonora non disponibile: apri UNVOR.").build();nm.notify(row.optString("id"),1,n);}catch(Exception ignored){}}
 static Notification notification(Context c,JSONObject row,String channel,boolean alarm){String id=row.optString("id");Intent open=new Intent(c,MainActivity.class).setData(android.net.Uri.parse("ultron-agenda://event/"+id)).putExtra("openAgenda",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent click=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification publicVersion=new Notification.Builder(c,channel).setSmallIcon(R.drawable.unvor_notification).setContentTitle("UNVOR").setContentText(alarm?"Sveglia agenda":"Promemoria agenda").build();
  Notification.Builder b=new Notification.Builder(c,channel).setLargeIcon(android.graphics.BitmapFactory.decodeResource(c.getResources(),R.drawable.ultron_face)).setSmallIcon(R.drawable.unvor_notification).setContentTitle(row.optString("title","UNVOR")).setContentText(row.optString("date")+" · "+row.optString("start")).setContentIntent(click).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(publicVersion).setCategory(alarm?Notification.CATEGORY_ALARM:Notification.CATEGORY_REMINDER).setAutoCancel(!alarm).setOngoing(alarm);
  if(alarm){PendingIntent stop=PendingIntent.getService(c,1,new Intent(c,AgendaAlarmService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.addAction(new Notification.Action.Builder(null,"Ferma sveglia",stop).build());}return b.build();
 }
}
